package org.apache.commons.math3.util;

import java.io.*;
import java.io.PrintStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for FastMath.cosh(double x).
 */
public class FastMath_cosh_TriageGen1Test {

    private static final double EPSILON = 1e-14;

    @Test
    public void testCoshNaN() {
        double nan = Double.NaN;
        assertEquals(nan, FastMath.cosh(nan), 0.0);
    }

    @Test
    public void testCoshZero() {
        // cosh(0) = (exp(0) + exp(0))/2 = 1
        assertEquals(1.0, FastMath.cosh(0.0), EPSILON);
    }

    @Test
    public void testCoshPositiveSmall() {
        // Test within the [-20, 20] range where high precision logic is used
        double x = 1.0;
        double expected = (Math.exp(x) + Math.exp(-x)) / 2.0;
        assertEquals(expected, FastMath.cosh(x), EPSILON);
    }

    @Test
    public void testCoshNegativeSmall() {
        // Test within the [-20, 20] range, ensuring x = -x logic is covered
        double x = -1.0;
        double expected = (Math.exp(x) + Math.exp(-x)) / 2.0;
        assertEquals(expected, FastMath.cosh(x), EPSILON);
    }

    @Test
    public void testCoshLargePositive() {
        // Test x > 20 branch to trigger overflow avoidance logic
        double x = 25.0;
        double expected = 0.5 * Math.exp(x);
        assertEquals(expected, FastMath.cosh(x), EPSILON);
    }

    @Test
    public void testCoshLargeNegative() {
        // Test x < -20 branch to trigger overflow avoidance logic
        double x = -25.0;
        double expected = 0.5 * Math.exp(-x);
        assertEquals(expected, FastMath.cosh(x), EPSILON);
    }

    @Test
    public void testCoshBoundaryPositive() {
        // Boundary test for the x > 20 condition
        double x = 20.0000000000001;
        double expected = 0.5 * Math.exp(x);
        assertEquals(expected, FastMath.cosh(x), EPSILON);
    }

    @Test
    public void testCoshBoundaryNegative() {
        // Boundary test for the x < -20 condition
        double x = -20.0000000000001;
        double expected = 0.5 * Math.exp(-x);
        assertEquals(expected, FastMath.cosh(x), EPSILON);
    }

    @Test
    public void testCoshSymmetry() {
        // cosh(x) should equal cosh(-x)
        double x = 5.5;
        assertEquals(FastMath.cosh(x), FastMath.cosh(-x), EPSILON);
    }
}
